"""The completion certificate (design §9.2): a PDF evidence summary generated by DocuMind."""

from __future__ import annotations

import hashlib
import io
from collections.abc import Sequence
from dataclasses import dataclass
from datetime import UTC, datetime
from typing import Any

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.units import mm
from reportlab.pdfgen.canvas import Canvas
from reportlab.platypus import (
    KeepTogether,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle,
)

from documind.infrastructure.signing import fonts

DISCLAIMER = (
    "Generated by DocuMind. This is an evidence summary, not a certificate issued by a "
    "government or trust-service provider."
)
ACCENT = colors.HexColor("#0e7490")  # the product accent colour
MUTED = colors.HexColor("#4b5563")
RULE = colors.HexColor("#d1d5db")


@dataclass(frozen=True, slots=True)
class CertificateRecipient:
    name: str
    email: str
    role: str  # signer or approver
    order: int
    auth_method: str
    action: str  # signed or approved
    acted_at: datetime | None
    consented_at: datetime | None = None
    ip_address: str | None = None


@dataclass(frozen=True, slots=True)
class CertificateData:
    agreement_id: str
    title: str
    sender_name: str
    sender_email: str
    routing: str
    source_sha256: str
    snapshot_sha256: str
    final_sha256: str
    sent_at: datetime | None
    completed_at: datetime
    chain_head: str
    recipients: Sequence[CertificateRecipient]
    generated_at: datetime | None = None


@dataclass(frozen=True, slots=True)
class Certificate:
    data: bytes
    sha256: str


def _when(value: datetime | None) -> str:
    if value is None:
        return "—"
    return value.astimezone(UTC).strftime("%Y-%m-%d %H:%M:%S UTC")


def _styles() -> dict[str, ParagraphStyle]:
    fonts.register()
    base = ParagraphStyle("base", fontName="DejaVuSans", fontSize=9, leading=12)
    return {
        "title": ParagraphStyle("title", base, fontName="DejaVuSans-Bold", fontSize=16, leading=20),
        "h2": ParagraphStyle(
            "h2", base, fontName="DejaVuSans-Bold", fontSize=11, leading=14, textColor=ACCENT
        ),
        "body": base,
        "label": ParagraphStyle("label", base, textColor=MUTED),
        "mono": ParagraphStyle("mono", base, fontSize=8, leading=10),
    }


def _p(text: str, style: ParagraphStyle) -> Paragraph:
    return Paragraph(fonts.markup(text), style)


def _facts(rows: Sequence[tuple[str, str]], s: dict[str, ParagraphStyle], mono: bool) -> Table:
    value_style = s["mono"] if mono else s["body"]
    table = Table(
        [[_p(k, s["label"]), _p(v, value_style)] for k, v in rows],
        colWidths=[42 * mm, None],
        hAlign="LEFT",
    )
    table.setStyle(
        TableStyle(
            [
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 0),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ]
        )
    )
    return table


def _recipient(r: CertificateRecipient, s: dict[str, ParagraphStyle]) -> Any:
    rows = [
        ("Email", r.email),
        ("Role", r.role.capitalize()),
        ("Signing order", str(r.order)),
        ("Authentication", r.auth_method.replace("_", " ")),
        ("Consent accepted", _when(r.consented_at)),
        (r.action.capitalize(), _when(r.acted_at)),
        ("IP address", r.ip_address or "—"),
    ]
    return KeepTogether([_p(r.name, s["h2"]), _facts(rows, s, mono=False), Spacer(1, 4 * mm)])


def _footer(canvas: Canvas, doc: Any) -> None:
    canvas.saveState()
    canvas.setStrokeColor(RULE)
    canvas.line(doc.leftMargin, 16 * mm, A4[0] - doc.rightMargin, 16 * mm)
    canvas.setFont("DejaVuSans", 7.5)
    canvas.setFillColor(MUTED)
    canvas.drawString(doc.leftMargin, 11 * mm, DISCLAIMER)
    canvas.drawRightString(A4[0] - doc.rightMargin, 7 * mm, f"Page {doc.page}")
    canvas.restoreState()


def render_certificate(data: CertificateData) -> Certificate:
    s = _styles()
    generated = data.generated_at or datetime.now(UTC)
    story: list[Any] = [
        _p("Completion certificate", s["title"]),
        Spacer(1, 2 * mm),
        _p(data.title, s["body"]),
        Spacer(1, 6 * mm),
        _p("Agreement", s["h2"]),
        _facts(
            [
                ("Agreement ID", data.agreement_id),
                ("Sent by", f"{data.sender_name} <{data.sender_email}>"),
                ("Signing order", data.routing),
                ("Sent", _when(data.sent_at)),
                ("Completed", _when(data.completed_at)),
                ("Certificate generated", _when(generated)),
            ],
            s,
            mono=False,
        ),
        Spacer(1, 4 * mm),
        _p("Document fingerprints (SHA-256)", s["h2"]),
        _facts(
            [
                ("Source document", data.source_sha256),
                ("Document sent for signature", data.snapshot_sha256),
                ("Signed document", data.final_sha256),
                ("Evidence chain head", data.chain_head),
            ],
            s,
            mono=True,
        ),
        Spacer(1, 6 * mm),
        _p("Recipients", s["h2"]),
        Spacer(1, 2 * mm),
    ]
    story += [_recipient(r, s) for r in sorted(data.recipients, key=lambda r: r.order)]
    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf,
        pagesize=A4,
        leftMargin=18 * mm,
        rightMargin=18 * mm,
        topMargin=18 * mm,
        bottomMargin=24 * mm,
        title=f"Completion certificate: {data.title}",
        author="DocuMind",
        creator="DocuMind Sign",
        invariant=True,
    )
    doc.build(story, onFirstPage=_footer, onLaterPages=_footer)
    pdf = buf.getvalue()
    return Certificate(data=pdf, sha256=hashlib.sha256(pdf).hexdigest())
